/* eslint-disable */
/**
 * FILE GENERATO — non modificare a mano.
 * Rigenerare con `npm run calendario`.
 *
 * Ogni riga è una diffusione:
 *   [data e ora UTC, periodo, previsto, effettivo, precedente, stadio?]
 *
 * Fonte: calendario economico pubblico di TradingView, che aggrega i
 * comunicati degli istituti di statistica e il consenso degli analisti.
 */
import { Cadence, Release, Stage } from '../models/calendar.model';

export const CALENDAR_GENERATED_AT = '2026-08-03T14:19Z';

type Row = readonly [
  at: string,
  period: string,
  forecast: number | null,
  actual: number | null,
  previous: number | null,
  stage?: Stage,
];

export interface SeriesData {
  readonly cadence: Cadence;
  readonly releases: readonly Release[];
  readonly next: Release | null;
  /** Riunioni già fissate dal calendario ufficiale dell’istituto. */
  readonly scheduled?: readonly string[];
}

const r = (rows: readonly Row[]): readonly Release[] =>
  rows.map(([at, period, forecast, actual, previous, stage]) => ({
    at,
    period,
    forecast,
    actual,
    previous,
    ...(stage ? { stage } : {}),
  }));

